const m = $('Build 8-Week Trend Chart').first().json;
let ai = $json.message?.content ?? {};
if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = {}; } }
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const link = w => `<a href="${m.base_url}/workflow/${w.workflow_id}">${esc(w.workflow_name)}</a>`;
const table = (title, rows, cols) => rows.length ? `<h3>${title}</h3><table border="1" cellpadding="6" style="border-collapse:collapse;font-size:13px">
<tr style="background:#f0f0f0">${cols.map(c => `<th>${c[0]}</th>`).join('')}</tr>
${rows.map(r => `<tr>${cols.map(c => `<td>${c[1](r)}</td>`).join('')}</tr>`).join('')}</table>` : '';
const list = (t, a) => (a && a.length) ? `<h3>${t}</h3><ul>${a.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '';
const t = m.totals, wow = m.wow;
const delta = (v, unit = '', invert = false) => {
  if (wow === null || v === undefined) return '';
  const bad = invert ? v < 0 : v > 0;
  return `<div style="font-size:11px;color:${v === 0 ? '#888' : bad ? '#c0392b' : '#27ae60'}">${v > 0 ? '▲' : v < 0 ? '▼' : '■'} ${Math.abs(v)}${unit} WoW</div>`;
};
const card = (k, v, d = '') => `<td style="padding:10px 16px;background:#f6f6f6;text-align:center"><div style="font-size:20px;font-weight:bold">${v}</div><div style="font-size:12px;color:#666">${k}</div>${d}</td>`;
const sevColor = s => s === 'high' ? '#c0392b' : s === 'medium' ? '#d35400' : '#2980b9';

const failing = m.workflows.filter(w => w.failed > 0).slice(0, 10);
const slow = [...m.workflows].filter(w => w.total > 0).sort((a, b) => b.p95_seconds - a.p95_seconds).slice(0, 8);
const spend = [...m.workflows].filter(w => w.cost_usd > 0).sort((a, b) => b.cost_usd - a.cost_usd).slice(0, 8);

const html = `<div style="font-family:Arial,sans-serif;max-width:860px">
<h2>n8n weekly health & cost digest</h2>
<p>${esc(ai.headline || '')} <b>Health score: ${ai.health_score ?? 'n/a'}/100</b></p>
<table cellspacing="6"><tr>
${card('Executions', t.executions, wow && delta(wow.executions, '', true))}
${card('Failed', t.failed, wow && delta(wow.failed))}
${card('Error rate', (t.error_rate * 100).toFixed(1) + '%', wow && delta(wow.error_rate_pts, ' pts'))}
${card('Est. LLM spend', '$' + t.cost_usd, wow && delta(wow.cost_usd, '$'))}
${card('Anomalies', m.anomalies.filter(a => a.severity !== 'info').length)}
${card('Error clusters', m.error_clusters.length)}</tr></table>
${m.trend_weeks >= 2 ? `<p><b>8-week trend:</b> failures ${m.failure_trend}</p><img src="${m.trend_chart_url}" width="760" alt="8-week trend" style="max-width:100%">` : ''}
${m.has_history ? '' : '<p style="color:#888">First run – trends and anomalies start next week once history exists.</p>'}
${list('Key findings', ai.key_findings)}${list('Likely root causes', ai.root_causes)}${list('Anomaly actions', ai.anomaly_actions)}${list('Cost actions', ai.cost_actions)}
${table('Anomalies vs 4-week baseline', m.anomalies.slice(0, 15), [['Severity', a => `<b style="color:${sevColor(a.severity)}">${a.severity.toUpperCase()}</b>`], ['Type', a => a.type.replace(/_/g, ' ')], ['Workflow', a => esc(a.workflow)], ['Detail', a => esc(a.detail)]])}
${table('Error clusters (latest failures)', m.error_clusters, [['Category', c => `<b>${c.category}</b>${c.cross_workflow ? '<br><small style="color:#c0392b">cross-workflow</small>' : ''}`], ['Seen', c => c.count], ['Workflows', c => esc(c.workflows.join(', '))], ['Node(s)', c => esc(c.nodes.join(', '))], ['Sample error', c => `<code style="font-size:11px">${esc(c.sample)}</code>`]])}
${table('Top failing workflows', failing, [['Workflow', link], ['Runs', w => w.total], ['Failed', w => w.failed], ['Error rate', w => (w.error_rate * 100).toFixed(1) + '%'], ['Last error', w => (w.last_error_at || '').slice(0, 16).replace('T', ' ')]])}
${table('Slowest workflows (p95)', slow, [['Workflow', link], ['Runs', w => w.total], ['Avg s', w => w.avg_seconds], ['p95 s', w => w.p95_seconds]])}
${table('LLM token spend by workflow', spend, [['Workflow', link], ['Model', w => esc(w.primary_model)], ['Tokens', w => (w.tokens_in + w.tokens_out).toLocaleString()], ['Est. cost', w => '$' + w.cost_usd]])}
<p style="color:#888;font-size:12px">Window from ${m.window_start.slice(0, 10)} · Cost is estimated from tokenUsage in execution data.</p></div>`;

const high = m.anomalies.filter(a => a.severity === 'high');
const slack_text = `:bar_chart: *n8n weekly digest* – health ${ai.health_score ?? 'n/a'}/100\n${ai.headline || ''}\n• ${t.executions} runs · ${t.failed} failed (${(t.error_rate * 100).toFixed(1)}%) · ~$${t.cost_usd} LLM spend${wow ? ` · WoW failures ${wow.failed >= 0 ? '+' : ''}${wow.failed}` : ''}\n${high.length ? `:rotating_light: ${high.map(a => `${a.workflow}: ${a.detail}`).slice(0, 5).join('\n:rotating_light: ')}\n` : ''}${m.error_clusters.filter(c => c.cross_workflow).map(c => `:link: ${c.category} error hitting ${c.workflows.length} workflows`).slice(0, 3).join('\n')}\nFull report sent to ${m.digest_email}`;

return [{ json: { to: m.digest_email, subject: `n8n weekly: ${t.failed} failures · ${(t.error_rate * 100).toFixed(1)}% error rate · ~$${t.cost_usd} LLM · ${high.length} high anomalies`, html, slack_text } }];

const m = $('Build 8-Week Trend Chart').first().json;
const rows = m.workflows.map(w => ({ json: {
  snapshot_date: m.snapshot_date, workflow_id: w.workflow_id, workflow_name: w.workflow_name,
  executions: w.total, failed: w.failed, error_rate: w.error_rate, p95_seconds: w.p95_seconds,
  cost_usd: w.cost_usd, tokens: w.tokens_in + w.tokens_out
}}));
rows.push({ json: { snapshot_date: m.snapshot_date, workflow_id: '__total__', workflow_name: 'ALL WORKFLOWS',
  executions: m.totals.executions, failed: m.totals.failed, error_rate: m.totals.error_rate, p95_seconds: '',
  cost_usd: m.totals.cost_usd, tokens: m.totals.tokens } });
return rows;

const c = $('Build Triage Context').item.json;
const cfg = $('Set Monitor Config').first().json;
const ai = $json.output || {};
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const incident_id = `INC-${$now.toFormat('yyyyLLdd-HHmm')}-${hex(4)}`;
const token = hex(24);
const act = a => `${cfg.actions_webhook_url}?id=${incident_id}&t=${token}&a=${a}`;
const wfUrl = `${c.base_url}/workflow/${c.workflow_id}`;
const execUrl = c.last_error_id && c.last_error_id !== 'none' ? `${wfUrl}/executions/${c.last_error_id}` : wfUrl;
const actionText = c.action === 'auto_disable' ? '🛑 Workflow auto-DEACTIVATED'
  : c.action === 'alert_only_protected' ? '⚠️ Protected – NOT disabled, needs manual action NOW' : '👀 Alert only – watching';
const buttons = [
  ...(c.action === 'auto_disable' ? [{ type: 'button', style: ai.safe_to_reenable ? 'primary' : undefined,
      text: { type: 'plain_text', text: ai.safe_to_reenable ? '▶️ Re-enable (AI: safe)' : '▶️ Re-enable anyway' }, url: act('reenable') }] : []),
  { type: 'button', text: { type: 'plain_text', text: '✅ Acknowledge' }, url: act('ack') },
  { type: 'button', text: { type: 'plain_text', text: `🔕 Snooze warnings ${cfg.snooze_hours}h` }, url: act('snooze') },
  { type: 'button', text: { type: 'plain_text', text: '🔎 Open execution' }, url: execUrl }
].map(b => { if (!b.style) delete b.style; return b; });
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `${c.severity === 'critical' ? '🚨 CRITICAL' : '⚠️ WARNING'} · ${c.workflow_name}`.slice(0, 150) } },
  { type: 'section', text: { type: 'mrkdwn', text: `*${actionText}*\n<${wfUrl}|Open workflow> · incident \`${incident_id}\`` } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Why*\n${c.reasons.join('\n')}` },
    { type: 'mrkdwn', text: `*Last hour*\n${c.total} runs · ${c.failed} failed · ~$${c.cost_usd} LLM` },
    { type: 'mrkdwn', text: `*Failing node*\n\`${c.failing_node}\` (${String(c.failing_node_type).split('.').pop()})` },
    { type: 'mrkdwn', text: `*Category*\n${ai.category || c.error_category}${c.transient ? ' (transient)' : ''}` } ] },
  { type: 'section', text: { type: 'mrkdwn', text: '*Error*\n```' + String(c.error_message || 'n/a').slice(0, 280) + '```' } },
  { type: 'section', text: { type: 'mrkdwn', text: `*🧠 Root cause* (${ai.confidence || '?'} confidence): ${ai.root_cause || 'not determined'}\n` +
      (ai.evidence || []).slice(0, 3).map(e => `• ${e}`).join('\n') +
      (ai.fix_steps?.length ? `\n*Fix:*\n${ai.fix_steps.slice(0, 4).map((s, i) => `${i + 1}. ${s}`).join('\n')}` : '') +
      (ai.suggested_node_settings ? `\n*Node setting:* ${ai.suggested_node_settings}` : '') } },
  ...(c.repeat_offender || ai.repeat_pattern ? [{ type: 'context', elements: [{ type: 'mrkdwn', text:
      `:repeat: ${c.repeat_offender ? `Disabled ${c.disables_7d + 1}× in 7 days. ` : ''}${ai.repeat_pattern || ''}` }] }] : []),
  ...(ai.blast_radius ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: `*Blast radius:* ${ai.blast_radius}` }] }] : []),
  { type: 'actions', elements: buttons }
];
const escalate = c.severity === 'critical' && (c.action === 'alert_only_protected' || c.repeat_offender || ai.confidence === 'Low' || ai.category === 'credentials');
return { json: { ...c, incident_id, token, ai_root_cause: ai.root_cause || '', ai_fix: (ai.fix_steps || []).join(' | '),
  ai_confidence: ai.confidence || '', safe_to_reenable: !!ai.safe_to_reenable, ai_category: ai.category || c.error_category,
  escalate, slack_blocks: blocks,
  slack_fallback: `${c.severity.toUpperCase()}: ${c.workflow_name} – ${ai.root_cause || c.reasons[0]}` } };

// Arrives from the Deactivate call (n8n API response) OR straight from the IF (alert-only)
const inc = $('Merge Triage & Build Alert').item.json;
const fromDeactivate = !$json.slack_blocks;
const deactivated = fromDeactivate ? $json.active === false : false;
const out = { ...inc, deactivated, action_result: !fromDeactivate ? inc.action : (deactivated ? 'deactivated' : 'deactivate_failed') };
if (fromDeactivate && !deactivated) {
  out.escalate = true;
  out.slack_blocks = [{ type: 'section', text: { type: 'mrkdwn', text:
    `:x: *Auto-deactivation FAILED* (${$json.error?.message || 'API did not confirm active=false'}). Deactivate it manually now.` } }, ...inc.slack_blocks];
}
return { json: out };

const q = $('On Slack Action Link Click').first().json.query || {};
const cfg = $input.first().json;
const inc = $('Look Up Incident in Guard Log').all().map(i => i.json).find(r => r.incident_id === q.id) || {};
const a = String(q.a || '').toLowerCase();
let reason = '';
if (!inc.incident_id) reason = 'Incident not found';
else if (!inc.token || inc.token === 'used' || q.t !== inc.token) reason = 'This link is invalid or was already used';
else if (!['reenable', 'ack', 'snooze'].includes(a)) reason = 'Unknown action';
else if (a === 'reenable' && inc.action_result !== 'deactivated') reason = 'Workflow was not auto-disabled by the guard';
const now = $now;
return [{ json: { ...inc, act: a, valid: !reason, reason, base_url: cfg.n8n_base_url,
  status: { reenable: 're-enabled', ack: 'acknowledged', snooze: 'snoozed' }[a] || '',
  snoozed_until: a === 'snooze' ? now.plus({ hours: cfg.snooze_hours }).toISO() : (inc.snoozed_until || ''),
  resolved_at: now.toISO() } }];
